L(s,[('t1','Static RAM (SRAM)','اسٹیٹک ریم (ایس ریم)','جامده RAM (SRAM)'),('t2','Dynamic RAM (DRAM)','ڈائنامک ریم (ڈی ریم)','متحرکه RAM (DRAM)')],'ram')
H(s,'h2','i. Static RAM (SRAM)','i۔ اسٹیٹک ریم (ایس ریم)','i. جامده RAM (SRAM)')
add(s,'b','(SRAM) is a type of semiconductor memory where the word “Static” indicates that it does not need to be periodically refreshed to retain its data. SRAM is more expensive, but faster and significantly less power hungry than DRAM. Due to a more complex internal structure, SRAM is less dense than DRAM and is therefore not used for high-capacity, low-cost applications such as the main memory in personal computers. Static RAM is mainly used to make the CPU’s cache.','ایس ریم نیم موصل میموری کی ایک قسم ہے جہاں لفظ ’’اسٹیٹک‘‘ اس بات کی طرف اشارہ کرتا ہے کہ اپنا ڈیٹا برقرار رکھنے کے لیے اسے وقتاً فوقتاً ری فریش کرنے کی ضرورت نہیں ہوتی۔ ایس ریم زیادہ مہنگی ہے لیکن ڈی ریم سے تیز اور نمایاں طور پر کم بجلی استعمال کرنے والی ہے۔ زیادہ پیچیدہ اندرونی ساخت کی وجہ سے ایس ریم ڈی ریم سے کم گنجان ہے اور اس لیے اسے زیادہ گنجائش اور کم لاگت والی ایپلیکیشنز جیسے پرسنل کمپیوٹرز کی مین میموری کے لیے استعمال نہیں کیا جاتا۔ اسٹیٹک ریم بنیادی طور پر سی پی یو کی کیش بنانے کے لیے استعمال ہوتی ہے۔','SRAM د نیمه تېرونکي حافظې یو ډول دی چېرته چې ټکی “جامد” ښیي چې خپل ډېټا ساتلو لپاره د وخت په وخت تازه کولو ته اړتیا نه لري. SRAM ډیره ګرانه ده خو ګړندۍ او له DRAM نه په څرګنده توګه لږ بریښنا اخلي. د ډیر پیچلي دننني جوړښت له امله SRAM له DRAM نه لږ ګنده ده او نو د لوړې ظرفیت، ټیټ لګښت اپلیکېشنونو لکه په شخصي کمپیوټرونو کې اصلي حافظې لپاره نه کارول کېږي. جامده RAM په عمده توګه د CPU د کېش جوړولو لپاره کارول کېږي.')
H(s,'h3','ii. Dynamic RAM','ii۔ ڈائنامک ریم','ii. متحرکه RAM')
add(s,'c','DRAM is a type of semiconductor memory where the word “Dynamic” indicates that it needs to be periodically refreshed to retain its data. It stores each bit of data in a separate capacitor within an integrated circuit. The capacitor can be either charged or discharged; these two states are taken to represent the two values of a bit, conventionally called 0 and 1. In personal computers DRAMs are used as internal memory because of their simple structure that allows high storage and low cost as compared to SRAM. There are two main types of DRAM.','ڈی ریم نیم موصل میموری کی ایک قسم ہے جہاں لفظ ’’ڈائنامک‘‘ اس بات کی طرف اشارہ کرتا ہے کہ اپنا ڈیٹا برقرار رکھنے کے لیے اسے وقتاً فوقتاً ری فریش کرنا پڑتا ہے۔ یہ ڈیٹا کا ہر بٹ ایک انٹیگریٹڈ سرکٹ کے اندر ایک الگ کپیسیٹر میں محفوظ کرتی ہے۔ کپیسیٹر یا تو چارج ہو سکتا ہے یا ڈسچارج؛ ان دو حالتوں کو بٹ کی دو قدروں کے لیے لیا جاتا ہے جنہیں روایتی طور پر ۰ اور ۱ کہتے ہیں۔ پرسنل کمپیوٹرز میں ڈی ریم اندرونی میموری کے طور پر استعمال ہوتی ہے کیونکہ ان کی سادہ ساخت ایس ریم کے مقابلے میں زیادہ ذخیرے اور کم لاگت کی اجازت دیتی ہے۔ ڈی ریم کی دو بنیادی اقسام ہیں۔','DRAM د نیمه تېرونکي حافظې یو ډول دی چېرته چې ټکی “متحرک” ښیي چې خپل ډېټا ساتلو لپاره باید وخت په وخت تازه شي. دا د ډېټا هر بټ په یوه ګډ سرکټ کې په یو جلا کپیسیټر کې ساتي. کپیسیټر کېدای شي یا چارج وي یا ډیسچارج؛ دا دوه حالتونه د بټ دوه ارزښتونو لپاره اخیستل کېږي چې په دود ورته ۰ او ۱ وايي. په شخصي کمپیوټرونو کې DRAMs د دننني حافظې په توګه کارول کېږي د هغوی د ساده جوړښت له امله چې د SRAM په پرتله لوړ ذخیره او ټیټ لګښت اجازه ورکوي. د DRAM دوه اصلي ډولونه شته.')
L(s,[('d1','SDRAM','ایس ڈی ریم','ایس ډي رام (SDRAM)'),('d2','DDR SDRAM','ڈی ڈی آر ایس ڈی ریم','ډي ډي آر ایس ډي رام (DDR SDRAM)')],'dram')
add(s,'d','SDRAM stands for Synchronous Dynamic Random Access Memory. SDRAM is a high speed semiconductor memory. It is an improved form of the older DRAM (Dynamic Random Access Memory). SDRAM operates synchronously, which means that it operates in sync with the','ایس ڈی ریم کا مطلب ہے سنکرونس ڈائنامک رینڈم ایکسیس میموری۔ ایس ڈی ریم ایک تیز رفتار نیم موصل میموری ہے۔ یہ پرانی ڈی ریم (ڈائنامک رینڈم ایکسیس میموری) کی بہتر شکل ہے۔ ایس ڈی ریم ہم وقت کام کرتی ہے، یعنی یہ','SDRAM د همغږي متحرکې تصادفي لاسرسي حافظې لنډیز دی. SDRAM د لوړ ګړندیتوب نیمه تېرونکې حافظه ده. دا د زړې DRAM (متحرکه تصادفي لاسرسي حافظه) ښه شوې بڼه ده. SDRAM همغږي کار کوي، مانا دا چې دا له',cont=True)
CAP(s,'c1','Figure 2.5 SDRAM','شکل ۲.۵ ایس ڈی ریم','انځور ۲.۵ SDRAM')
F.done()
